from typing import List

def minimum_swaps_for_maximum_score(arr: List[int]) -> int:
    n = len(arr)
    s = sorted(arr)
    partner = {}
    for k in range(n // 2):               # optimal pairs: k-th smallest with k-th largest
        a, b = s[k], s[n - 1 - k]
        partner[a], partner[b] = b, a
    slot = {v: i // 2 for i, v in enumerate(arr)}
    parent = list(range(n // 2))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    comps = n // 2
    for v in arr:                          # edge: slot(v) -- slot(partner(v))
        a, b = find(slot[v]), find(slot[partner[v]])
        if a != b:
            parent[a] = b
            comps -= 1
    return n // 2 - comps
